/**
 * B20 — the precomputed Holi / Diwali 2027 muhurats (generated by scripts/gen-muhurat2027.mts from
 * muhurat2027.ts; muhurat2027.test.tsx keeps the two identical). The pages read this, not the engine.
 */
import DATA from './muhurat2027.data.json';
import { CITIES, type City } from './muhuratFormat';
import type { Holika2027, Diwali2027 } from './muhurat2027';

const city = (id: string): City => CITIES.find(c => c.id === id)!;
const withCity = <T extends { city: string }>(x: T) => ({ ...x, city: city(x.city) });

export const HOLIKA_2027 = { ...DATA.holika, cities: DATA.holika.cities.map(withCity) } as unknown as Holika2027;
export const DIWALI_2027 = {
  ...DATA.diwali, cities: DATA.diwali.cities.map(withCity),
  dhanteras: { ...DATA.diwali.dhanteras, cities: DATA.diwali.dhanteras.cities.map(withCity) },
} as unknown as Diwali2027;
export { hm, istDate, icsEvent, type Win } from './muhuratFormat';
